/**
 * FSRS-4.5 active-recall scheduling — a line-for-line port of `backend/domain/memory/fsrs.py`.
 *
 * Pure and deterministic: nothing here reads the clock, settings or storage. Every instant arrives
 * through `reviewedAt`. Parity with the Python implementation is enforced by
 * `tests/fsrs.test.ts` against vectors generated by `scripts/gen_fsrs_golden.py`.
 *
 * Card memory is not problem-solving ability: this module never produces a score, a grade or a
 * knowledge state (invariant R-INV-04/08 — review does not write learning evidence).
 */
import { addDays, secondsBetween, type Instant } from './instant.ts'

export const FSRS_VERSION = 'fsrs-4.5-default-v1'

export const DEFAULT_WEIGHTS: readonly number[] = [
  0.4872, 1.4003, 3.7145, 13.8206, 5.1618, 1.2298, 0.8975, 0.031, 1.6474, 0.1367, 1.0461, 2.1072,
  0.0793, 0.3246, 1.587, 0.2272, 2.8755,
]

/** `params_version` -> weights. Old versions stay registered so stored cards replay identically. */
export const WEIGHTS_BY_VERSION: Readonly<Record<string, readonly number[]>> = {
  [FSRS_VERSION]: DEFAULT_WEIGHTS,
}

export const DEFAULT_DESIRED_RETENTION = 0.9
export const DECAY = -0.5
export const FACTOR = 19 / 81
export const MAX_INTERVAL_DAYS = 36500

export const RATINGS = ['again', 'hard', 'good', 'easy'] as const
export type Rating = (typeof RATINGS)[number]
const GRADE: Record<Rating, number> = { again: 1, hard: 2, good: 3, easy: 4 }

export const PHASES = ['new', 'learning', 'review', 'relearning'] as const
export type Phase = (typeof PHASES)[number]

export const LEARNING_STEP_MINUTES: readonly number[] = [1, 10]
export const HARD_STEP_MINUTES = 5
const MINUTES_PER_DAY = 1440

export interface CardState {
  stability: number
  difficulty: number
  phase: Phase
  reps: number
  lapses: number
  learningStep: number
  lastReviewedAt: Instant | null
  dueAt: Instant | null
  scheduledDays: number
  elapsedDays: number
}

export interface ScheduleResult {
  state: CardState
  retrievability: number
  intervalDays: number
  elapsedDays: number
  phaseAfter: Phase
  isLapse: boolean
  schedulerVersion: string
}

export function newCard(): CardState {
  return {
    stability: 0, difficulty: 0, phase: 'new', reps: 0, lapses: 0, learningStep: 0,
    lastReviewedAt: null, dueAt: null, scheduledDays: 0, elapsedDays: 0,
  }
}

function normalizeRating(rating: string): Rating {
  const text = String(rating).trim().toLowerCase()
  if (!(text in GRADE)) throw new Error(`unknown memory rating: ${JSON.stringify(rating)}`)
  return text as Rating
}

function validateWeights(weights: readonly number[]): readonly number[] {
  if (weights.length !== 17) throw new Error(`FSRS-4.5 needs exactly 17 weights, got ${weights.length}`)
  return weights.map(Number)
}

/** Weights for one `params_version`; an unknown version is an error, never a silent fallback. */
export function weightsFor(paramsVersion: string): readonly number[] {
  const weights = WEIGHTS_BY_VERSION[paramsVersion]
  if (!weights) throw new Error(`unknown FSRS params_version: ${JSON.stringify(paramsVersion)}`)
  return weights
}

export function clampDifficulty(value: number): number {
  return Math.min(10, Math.max(1, Number(value)))
}

/** `R(t, S)`; a card without memory (S <= 0) has nothing to decay -> 1. */
export function retrievability(elapsedDays: number, stability: number): number {
  if (stability <= 0) return 1
  const elapsed = Math.max(0, Number(elapsedDays))
  const value = (1 + (FACTOR * elapsed) / stability) ** DECAY
  return Math.min(1, Math.max(0, value))
}

export function initialStability(rating: string, weights: readonly number[] = DEFAULT_WEIGHTS): number {
  return Number(validateWeights(weights)[GRADE[normalizeRating(rating)] - 1])
}

export function initialDifficulty(rating: string, weights: readonly number[] = DEFAULT_WEIGHTS): number {
  const w = validateWeights(weights)
  return clampDifficulty(w[4] - (GRADE[normalizeRating(rating)] - 3) * w[5])
}

/** `I(S)` rounded half-up with `floor(x + 0.5)` (never banker's rounding), clamped to [1, 36500]. */
export function nextIntervalDays(stability: number, desiredRetention = DEFAULT_DESIRED_RETENTION): number {
  if (stability <= 0) return 1
  const retention = Math.min(0.99, Math.max(0.05, Number(desiredRetention)))
  const raw = (stability / FACTOR) * (retention ** (1 / DECAY) - 1)
  return Math.min(MAX_INTERVAL_DAYS, Math.max(1, Math.floor(raw + 0.5)))
}

export function recallStability(
  stability: number, difficulty: number, retrievabilityValue: number, rating: string,
  weights: readonly number[] = DEFAULT_WEIGHTS,
): number {
  const w = validateWeights(weights)
  const grade = GRADE[normalizeRating(rating)]
  const hardPenalty = grade === 2 ? w[15] : 1
  const easyBonus = grade === 4 ? w[16] : 1
  const growth =
    Math.exp(w[8]) * (11 - difficulty) * stability ** -w[9] *
    (Math.exp((1 - retrievabilityValue) * w[10]) - 1) * hardPenalty * easyBonus
  return Math.max(0.01, stability * (1 + growth))
}

export function forgetStability(
  stability: number, difficulty: number, retrievabilityValue: number,
  weights: readonly number[] = DEFAULT_WEIGHTS,
): number {
  const w = validateWeights(weights)
  const value =
    w[11] * difficulty ** -w[12] * ((stability + 1) ** w[13] - 1) * Math.exp((1 - retrievabilityValue) * w[14])
  return Math.max(0.01, value)
}

export function nextDifficulty(difficulty: number, rating: string, weights: readonly number[] = DEFAULT_WEIGHTS): number {
  const w = validateWeights(weights)
  const shifted = difficulty - w[6] * (GRADE[normalizeRating(rating)] - 3)
  return clampDifficulty(w[7] * w[4] + (1 - w[7]) * shifted)
}

const stepMinutes = (step: number): number =>
  LEARNING_STEP_MINUTES[Math.min(Math.max(0, Math.trunc(step)), LEARNING_STEP_MINUTES.length - 1)]
const minutes = (m: number): number => Number(m) / MINUTES_PER_DAY

interface ScheduleOptions { weights?: readonly number[]; desiredRetention?: number }

/** Schedule one review of `state` at `reviewedAt`. Same inputs always yield the same result. */
export function schedule(
  state: CardState, rating: string, reviewedAt: Instant, options: ScheduleOptions = {},
): ScheduleResult {
  const weights = validateWeights(options.weights ?? DEFAULT_WEIGHTS)
  const desiredRetention = options.desiredRetention ?? DEFAULT_DESIRED_RETENTION
  const grade = normalizeRating(rating)
  const phase = (state.phase || 'new') as Phase
  if (!PHASES.includes(phase)) throw new Error(`unknown memory card phase: ${JSON.stringify(state.phase)}`)

  const prevStability = Number(state.stability || 0)
  const prevDifficulty = Number(state.difficulty || 0)
  let elapsedDays = 0
  if (state.lastReviewedAt !== null) {
    elapsedDays = Math.max(0, secondsBetween(reviewedAt, state.lastReviewedAt) / 86400)
  }

  const isFirst = state.reps <= 0 || prevStability <= 0
  const observed = retrievability(elapsedDays, prevStability)

  let stability: number
  let difficulty: number
  let isLapse: boolean
  if (isFirst) {
    stability = initialStability(grade, weights)
    difficulty = initialDifficulty(grade, weights)
    isLapse = false
  } else {
    difficulty = nextDifficulty(prevDifficulty, grade, weights)
    if (grade === 'again') {
      // Only forgetting a graduated (`review`) card is a lapse; a slip in the short steps is not.
      isLapse = phase === 'review'
      stability = isLapse ? forgetStability(prevStability, prevDifficulty, observed, weights) : prevStability
    } else {
      isLapse = false
      stability = recallStability(prevStability, prevDifficulty, observed, grade, weights)
    }
  }

  let phaseAfter: Phase
  let learningStep: number
  let intervalDays: number
  if (phase === 'review' && !isFirst) {
    phaseAfter = grade !== 'again' ? 'review' : 'relearning'
    learningStep = grade === 'again' ? 0 : state.learningStep
    intervalDays = nextIntervalDays(stability, desiredRetention)
    if (grade === 'again') intervalDays = minutes(stepMinutes(0))
  } else {
    ;[phaseAfter, learningStep, intervalDays] = scheduleShortStep({
      phase, rating: grade, learningStep: state.learningStep, stability, isLapse, desiredRetention,
    })
  }

  const next: CardState = {
    stability, difficulty, phase: phaseAfter, reps: state.reps + 1,
    lapses: state.lapses + (isLapse ? 1 : 0), learningStep,
    lastReviewedAt: reviewedAt, dueAt: addDays(reviewedAt, intervalDays),
    scheduledDays: intervalDays, elapsedDays,
  }
  return { state: next, retrievability: observed, intervalDays, elapsedDays, phaseAfter, isLapse, schedulerVersion: FSRS_VERSION }
}

function scheduleShortStep(a: {
  phase: Phase; rating: Rating; learningStep: number; stability: number; isLapse: boolean; desiredRetention: number
}): [Phase, number, number] {
  // `relearning` is sticky until the card answers good/easy again.
  const stay: Phase = a.phase === 'relearning' || a.isLapse ? 'relearning' : 'learning'
  if (a.rating === 'again') return [stay, 0, minutes(stepMinutes(0))]
  if (a.rating === 'hard') return [stay, Math.trunc(a.learningStep), minutes(HARD_STEP_MINUTES)]
  if (a.rating === 'easy') return ['review', 0, nextIntervalDays(a.stability, a.desiredRetention)]
  const completed = Math.trunc(a.learningStep) + 1
  if (completed >= LEARNING_STEP_MINUTES.length) return ['review', 0, nextIntervalDays(a.stability, a.desiredRetention)]
  return [stay, completed, minutes(stepMinutes(completed))]
}
